/// <summary>
/// Service class for sales order finalization automate.
/// </summary>
class METSalesOrderFinalizationAutomateService
{
    FromDate        fromDate;
    ToDate          toDate;
    List            warehouseList;

}

Method.Source:
/// <summary>
/// Method to initiate business process
/// </summary>
/// <param name = "_contract">Contract class reference</param>
public void executeOperation(METSalesOrderFinalizationAutomateContract _contract)
{
    QueryRun                        queryRun;
    Query                           query = new Query();
    QueryBuildDataSource            qbdsLoadHeader = query.addDataSource(tableNum(METSalesOrderShipmentLoadHeader));
    QueryBuildRange                 warehouseRange;
    METSalesOrderShipmentLoadHeader metSalesOrderShipmentLoadHeader;
    ListIterator                    literator;
    Map                             filteredMap = new Map(Types::Int64, Types::String);

    warehouseList = _contract.parmWarehouseList();
    fromDate = _contract.parmFromDate();
    toDate = _contract.parmToDate();

    qbdsLoadHeader.addRange(fieldNum(METSalesOrderShipmentLoadHeader, ConfirmedShipDate)).value(queryRange(fromDate, toDate));
    qbdsLoadHeader.addRange(fieldNum(METSalesOrderShipmentLoadHeader, ShipmentStatus)).value(queryValue(MetShipmentStatus::Open));
    literator = new ListIterator(warehouseList);

    while (literator.more())
    {
        warehouseRange = qbdsLoadHeader.addRange(fieldNum(METSalesOrderShipmentLoadHeader, Warehouse));
        warehouseRange.value(queryValue(literator.value()));
        literator.next();
    }

    queryRun = new QueryRun(query);

    while (queryrun.next())
    {
        metSalesOrderShipmentLoadHeader = queryRun.get(tableNum(METSalesOrderShipmentLoadHeader));

        if (metSalesOrderShipmentLoadHeader.displayLoadPickComplete() == NoYes::Yes)
        {
            filteredMap.insert(metSalesOrderShipmentLoadHeader.RecId, metSalesOrderShipmentLoadHeader.ShipmentId);
        }
    }

    METShipmentPackingSlipCreate::initiateSalesShipmentConfirmation(filteredMap);
}
